theorem ComputesInTime.of_spaceUsed_le {M : FinTM Bool} {x w : List Bool} {t s : ℕ}
    (h : M.ComputesInTime x w t) (hs : M.tm.spaceUsed (M.tm.initCfg x) t ≤ s) :
    M.ComputesInTime x w (M.configBound x.length s)

lemma controlAction_apply {k : ℕ} {S : Type} {x : List Bool}
    (cfg : Cfg k Bool S x) (m : SignType) (q : Option S) :
    (controlAction m q).apply cfg =
      {cfg with state := q, inputPos := moveInputPos cfg.inputPos m}

theorem coreSum_stepWith (tm : NDTM k Bool S) (b : Bool) {c d : Cfg k Bool S x}
    (h : coreSum c = coreSum d) :
    coreSum (tm.stepWith b c) = coreSum (tm.stepWith b d)

theorem step_of_inputMoveAction {Symbol State : Type*} {k : ℕ} {x : List Symbol}
    (M : MultiTapeTM k Symbol State) (c : Cfg k Symbol State x) {q q' : State}
    (inp : SignType) (hq : c.state = some q)
    (htr : M.tr q c.inputSymbol c.workTapeSymbols = inputMoveAction inp q') :
    M.step c = { c with state := some q', inputPos := moveInputPos c.inputPos inp }

theorem coreSum_eq_of_cfgWord_eq {s : ℕ} {C D : Cfg N.k Bool N.State x}
    (hC : Cfg.InWindow s C) (hD : Cfg.InWindow s D) (h : cfgWord s C = cfgWord s D) :
    NDTM.coreSum C = NDTM.coreSum D

theorem haltsWithin_of_codes {sp : ℕ → ℕ} (hN : N.UsesSpace sp) (hs : sp x.length ≤ s)
    (hV : 2 ^ (codeK N * (s + logSpace x.length + 1)) ≤ V) {T : ℕ}
    (hT : N.tm.HaltsWithin x T) : N.tm.HaltsWithin x V

theorem boot_step (b : Bool) (c : Cfg S.k Bool S.State x) {q : S.State}
    (hq : c.state = some q) :
    (hostTM S A loop).stepWith b (bootCfg (A := A) c) = bootCfg (S.tm.step c)

theorem Cfg.mapState_const_eq_mapState_sigma {k : ℕ} {Γ I S : Type*} {Ph : I → Type*}
    {x : List Γ} {i : I} (c : Cfg k Γ S x) (c₂ : Cfg k Γ (Ph i) x) {q : Ph i}
    (hc : c.state.isSome) (hstate : c₂.state = some q) (hin : c.inputPos = c₂.inputPos)
    (hw : c.workTapes = c₂.workTapes) (hp : c.workTapePos = c₂.workTapePos)
    (ho : c.output = c₂.output) :
    c.mapState (fun _ => (⟨i, q⟩ : Σ j, Ph j)) = c₂.mapState (Sigma.mk i)

